export type FunnelTag = 'Lead Capture' | 'Booking' | 'Checkout' | 'Website'

export type Funnel = {
  file: string
  label: string
  tag: FunnelTag
  desc: string
  /** Public subfolder the HTML + thumbnail live under. Default 'funnels'. */
  dir?: 'funnels' | 'samples'
}

/**
 * Funnel pages and website samples. The pages themselves are still the sample
 * pages generated by scripts/make-placeholder-sites.mjs.
 *
 * To add your own: drop the page's HTML in public/funnels/ (single pages) or
 * public/samples/ (full websites), add an entry here, then run
 * `node scripts/make-thumbs.mjs` to render its thumbnails.
 */

const FUNNEL_DESC: Record<Exclude<FunnelTag, 'Website'>, string> = {
  'Lead Capture': 'An opt-in page that captures the lead and sends it straight into the CRM and follow-up.',
  Booking: 'A booking page wired to the calendar, with confirmations and reminders after.',
  Checkout: 'A checkout page connected to the CRM, so every purchase is tagged and followed up.',
}

const funnel = (n: string, tag: Exclude<FunnelTag, 'Website'>): Funnel => ({
  file: `placeholder-funnel-${n}.html`,
  label: `${tag} page ${n}`,
  tag,
  desc: FUNNEL_DESC[tag],
})

const site = (n: string): Funnel => ({
  file: `placeholder-site-${n}.html`,
  label: `Website sample ${n}`,
  tag: 'Website',
  desc: 'A sample website with forms and booking wired in. Project details coming soon.',
  dir: 'samples',
})

export const gymFunnel: Funnel[] = [
  funnel('01', 'Lead Capture'),
  funnel('02', 'Checkout'),
  funnel('03', 'Lead Capture'),
]

export const bookingFunnel: Funnel[] = [
  funnel('04', 'Booking'),
  funnel('05', 'Booking'),
  funnel('06', 'Booking'),
]

export const websiteFunnel: Funnel[] = ['01', '02', '03', '04', '05', '06'].map(site)

/**
 * Tag -> color map. Brand-external colors that identify the page type, passed
 * to CSS via an inline --tag-color custom property.
 */
export const tagColors: Record<FunnelTag, string> = {
  'Lead Capture': '#8b5cf6',
  Booking: '#ec4899',
  Checkout: '#f59e0b',
  Website: '#FF7A1A',
}
